import * as M from './model.js';
import * as P from './planner.js';

export const NOTE_COLORS=['yellow','blue','pink','green'];
export const FILE_KINDS={plan:'계획서',roster:'학생명렬표',lesson:'수업자료',minutes:'회의록',custom:'기타문서'};
export const defaults=()=>({schema:1,nextId:1,notes:[],files:[],official:[],weeks:{}});
export const data=s=>s.computer??=defaults();
const uid=(s,prefix)=>{const pc=data(s);let id;do{id=prefix+'-'+pc.nextId++;}while([...pc.notes,...pc.files].some(x=>x.id===id));return id;};
const currentSchool=s=>M.REGIONS[s.config.region].school;
const className=s=>`${s.config.grade}학년 ${M.REGIONS[s.config.region].classes===1?1:2}반`;
const TEMPLATES=[
 {title:'학급 학습준비물 활용 계획 제출',from:'교무기획부',kind:'report',required:'plan',body:'학급 교육활동에 필요한 준비물을 확인하여 활용 계획을 제출해 주세요.\n\n1. 대상과 활동 내용을 적어 주세요.\n2. 보유 교구와 구입할 물품을 구분해 주세요.\n3. 학급 준비물비 범위 안에서 계획해 주세요.\n\n붙임  학급 준비물 활용 계획 1부.'},
 {title:'학급 학생명렬표 확인 요청',from:'학적 담당',kind:'report',required:'roster',body:'현재 학급의 번호와 이름을 확인하여 학생명렬표를 제출해 주세요.\n\n1. 오늘 기준 학급 인원을 확인해 주세요.\n2. 작성일이 표시된 명렬표를 첨부해 주세요.\n3. 상담·가정환경 등 개인 메모는 첨부하지 않습니다.\n\n붙임  학생명렬표 1부.'},
 {title:'동학년 수업자료 나눔',from:'학년 교육과정 담당',kind:'report',required:'lesson',body:'이번 주 수업에서 활용할 자료와 학생 참여 방법을 함께 나누고자 합니다.\n\n1. 과목과 활동 목표를 적어 주세요.\n2. 학생들이 선택할 수 있는 표현 방법을 적어 주세요.\n3. 사용한 뒤 확인할 점을 덧붙여 주세요.\n\n붙임  수업자료 1부.'},
 {title:'공용 교구 정리와 반납 안내',from:'체육 담당',kind:'notice',required:null,body:'체육관과 운동장의 공용 교구를 다음 학급도 사용할 수 있도록 정리해 주세요.\n\n사용 전 수량과 상태 확인 → 활동 구역 정하기 → 사용 후 수량 확인 → 보관 위치에 반납\n\n매트는 실내에서 사용합니다. 필요한 교구는 현장의 체육도구 창에서 고를 수 있습니다.'},
 {title:'교실 시설 점검 협조 안내',from:'행정실',kind:'notice',required:null,body:'교실 시설의 이상을 발견하면 위치와 증상을 학교톡으로 알려 주세요.\n\n수업에 필요한 대체 자료를 준비하고 담당자의 점검 결과를 확인합니다. 시설 수리비는 학급 학습준비물비에서 차감하지 않습니다.'},
 {title:'학생 참여 중심 활동 계획 공유',from:'교육연구부',kind:'report',required:'plan',body:'학생의 배움 속도와 표현 방법을 고려한 학급 활동 계획을 공유해 주세요.\n\n목적·대상·기간·활동·준비물·확인 방법을 포함하고, 실제 수업 시간표와 겹치지 않게 준비해 주세요.\n\n붙임  학급 활동 계획 1부.'}
];
export function sync(s){const pc=data(s),week=Math.floor(s.day/5);if(!pc.weeks[week]){pc.weeks[week]=true;for(let i=0;i<2;i++){const t=TEMPLATES[(week*2+i)%TEMPLATES.length],id=`official-${week}-${i}`,doc={...t,id,number:`${currentSchool(s)}-${String(week*2+i+1).padStart(3,'0')}`,received:M.stamp(s),day:s.day,due:Math.min(M.demoDays(s)-1,week*5+4),status:'received',read:false,reply:'',attachments:[],history:[{date:M.stamp(s),text:'담임 업무로 접수'}],revision:0};pc.official.push(doc);}M.addMessage(s,'grade','윤서진','교사 PC 공문함에 이번 주 안내와 제출 요청을 전달했어요. 필요한 자료를 만들고 마감일을 확인해 주세요.',{senderId:'colleague',plannerScanned:true});}
 for(const doc of pc.official){if(doc.status==='submitted'&&(s.day>doc.reviewDay||s.day===doc.reviewDay&&s.minute>=doc.reviewMinute))review(s,doc);P.upsert(s,{id:'pc-task-'+doc.id,title:doc.title,day:doc.due,start:980,end:1000,room:'classroom',type:'task',source:'교사 PC 공문함',officialId:doc.id,status:doc.status==='completed'?'완료':'예정',response:'참석'});}
 return pc;
}
function canWork(s,minutes){const slot=M.currentSlot(s);return ['afternoon','specialist','morning','break'].includes(slot.kind)&&stateFree(s)&&s.minute+minutes<=Math.min(slot.end,1000)&&!P.conflicts(s,s.day,s.minute,s.minute+minutes).length;}
function stateFree(s){return !M.movementBusy(s)&&!(s.journey?.status==='arrived'&&s.journey.to!=='classroom');}
export function note(s,id,patch={}){const pc=data(s);let n=pc.notes.find(n=>n.id===id);if(!n){if(pc.notes.length>=100)return null;n={id:uid(s,'sticky'),title:'새 메모',text:'',color:'yellow',pinned:false,archived:false,created:M.stamp(s),updated:M.stamp(s)};pc.notes.unshift(n);}const before=JSON.stringify([n.title,n.text,n.color,n.pinned,n.archived]);if(typeof patch.title==='string')n.title=patch.title.slice(0,60);if(typeof patch.text==='string')n.text=patch.text.slice(0,2000);if(NOTE_COLORS.includes(patch.color))n.color=patch.color;if(typeof patch.pinned==='boolean')n.pinned=patch.pinned;if(typeof patch.archived==='boolean')n.archived=patch.archived;if(before!==JSON.stringify([n.title,n.text,n.color,n.pinned,n.archived]))n.updated=M.stamp(s);return n;}
export function createFile(s,kind='custom',sourceId){const pc=data(s);if(!FILE_KINDS[kind]||pc.files.length>=200)return null;let title,body;const heading=`${currentSchool(s)} ${className(s)}\n담임: ${s.config.teacherName}\n작성: ${M.stamp(s)}`;
 if(kind==='roster'){title=className(s)+' 학생명렬표';body=heading+'\n\n번호\t이름\t성별\n'+s.students.map((st,i)=>`${i+1}\t${st.name}\t${st.gender}`).join('\n')+`\n\n총 ${s.students.length}명`;}
 else if(kind==='plan'){title=className(s)+' 학급 활동 계획';body=heading+`\n\n1. 목적: 학생 모두가 참여할 수 있는 학급 활동\n2. 대상: ${s.students.length}명\n3. 기간: ${M.dateLabel(s)} 이후 학급 시간표에 맞춰 운영\n4. 주요 활동: [작성]\n5. 준비물·공간: 보유 교구를 우선 활용\n6. 학급 준비물비 잔액: ${s.budget.toLocaleString('ko-KR')}원\n7. 확인 방법: 참여 과정 관찰 후 다음 활동에 반영`;}
 else if(kind==='lesson'){title=className(s)+' 수업자료';body=heading+'\n\n과목: [작성]\n활동 목표: [작성]\n도입: 알고 있는 것 나누기\n활동: 말·그림·짝 설명 중 표현 방법 고르기\n정리: 새로 알게 된 점과 남은 질문\n관찰할 점: 참여 방법과 다시 시도한 장면';}
 else if(kind==='minutes'){const e=P.data(s).entries.find(e=>e.id===sourceId&&e.type==='meeting'&&e.status==='완료');if(!e)return null;const existing=pc.files.find(f=>f.kind==='minutes'&&f.sourceId===sourceId);if(existing)return existing;title=e.title+' 회의록';body=`${currentSchool(s)}\n${title}\n\n일시: ${M.dateLabel({day:e.day})} ${M.clock(e.start)}–${M.clock(e.end)}\n장소: ${M.ROOMS[e.room].name}\n확인된 참석자: ${s.config.teacherName}, ${M.NPCS.find(n=>n.id===e.personId)?.name||'담당 교사'}\n안건: ${P.GRADE_AGENDAS[e.agenda]?.name||e.title}\n\n협의 내용\n${e.note||'추가 기록 없음'}\n${e.discussion||''}\n\n후속 준비\n${P.data(s).entries.filter(t=>t.originMeeting===e.id).map(t=>`${t.title} / 점검 ${M.dateLabel({day:t.day})} / ${t.status}`).join('\n')||'추가 등록된 과제 없음'}\n\n참석 기록: ${e.completed||M.stamp(s)}`;}
 else{title='새 문서';body=heading+'\n\n';}
 const f={id:uid(s,'file'),kind,title,body,created:M.stamp(s),updated:M.stamp(s),archived:false,...(sourceId?{sourceId}:{})};pc.files.unshift(f);return f;
}
export function editFile(s,id,title,body){const f=data(s).files.find(f=>f.id===id);if(!f)return false;if(f.title===String(title||'제목 없는 문서').slice(0,100)&&f.body===String(body||'').slice(0,12000))return f;f.title=String(title||'제목 없는 문서').slice(0,100);f.body=String(body||'').slice(0,12000);f.updated=M.stamp(s);return f;}
export function openOfficial(s,id){const d=data(s).official.find(d=>d.id===id);if(d)d.read=true;return d;}
export function saveDraft(s,id,reply,attachments){const d=data(s).official.find(d=>d.id===id);if(!d||['submitted','approved','completed'].includes(d.status))return false;if(d.reply===String(reply||'').slice(0,3000)&&JSON.stringify(d.attachments)===JSON.stringify(attachments||[]))return true;d.reply=String(reply||'').slice(0,3000);d.attachments=[...new Set(attachments||[])].filter(id=>data(s).files.some(f=>f.id===id)).slice(0,5);if(d.status!=='revision')d.status='draft';d.updated=M.stamp(s);return true;}
export function submit(s,id){const d=data(s).official.find(d=>d.id===id);if(!d||d.kind!=='report'||!['received','draft','revision'].includes(d.status))return {error:'제출할 수 있는 공문을 선택해 주세요.'};if(d.reply.trim().length<20)return {error:'기안 내용을 20자 이상 작성해 주세요.'};if(!canWork(s,5))return {error:'수업·약속과 겹치지 않는 업무 시간 5분이 필요합니다.'};if(s.day===M.demoDays(s)-1&&s.minute+20>1000)return {error:'마지막 날에는 기안과 검토에 필요한 20분을 남겨 주세요.'};const snapshot=d.attachments.map(id=>data(s).files.find(f=>f.id===id)).filter(Boolean).map(f=>({id:f.id,kind:f.kind,title:f.title,body:f.body}));M.advance(s,5);d.status='submitted';d.submission={text:d.reply,attachments:snapshot,date:M.stamp(s)};d.reviewDay=s.minute+15>1000?Math.min(M.demoDays(s)-1,s.day+1):s.day;d.reviewMinute=s.minute+15>1000?535:s.minute+15;d.history.push({date:M.stamp(s),text:'기안 상신 · 교감 검토 대기'});M.addMessage(s,'all','나',d.title+' 기안을 올렸습니다. 첨부 '+snapshot.length+'건을 확인해 주세요.',{senderId:'teacher',plannerScanned:true});return {ok:true};}
function review(s,d){const attached=d.submission.attachments.find(f=>f.kind===d.required);const reason=!attached?`${FILE_KINDS[d.required]} 첨부가 필요합니다.`:/\[작성\]/.test(attached.body)?'첨부 문서의 [작성] 부분을 실제 활동 내용으로 채워 주세요.':attached.body.trim().length<30?'첨부 문서의 활동 내용을 조금 더 구체적으로 적어 주세요.':null;d.status=reason?'revision':'approved';d.feedback=reason||'대상·내용·첨부를 확인했습니다. 최종 제출 후 관련 업무에 활용해 주세요.';if(reason)d.revision++;d.history.push({date:M.stamp(s),text:reason?'보완 요청 · '+reason:'결재 완료 · 최종 제출 가능'});M.addMessage(s,'all','한정우',d.title+' · '+d.feedback,{senderId:'principal',plannerScanned:true});}
export function waitReview(s,id){const d=data(s).official.find(d=>d.id===id);if(!d||d.status!=='submitted')return {error:'검토 중인 기안을 선택해 주세요.'};const minutes=d.reviewMinute-s.minute;if(d.reviewDay!==s.day||minutes<0||!canWork(s,minutes))return {error:'다른 일정이 없는 시간에 결재 상태를 확인해 주세요. 게임 시간이 지나면 결과가 학교톡으로 도착합니다.'};M.advance(s,minutes);sync(s);return {ok:true};}
export function finishOfficial(s,id){const d=data(s).official.find(d=>d.id===id);if(!d||d.status==='completed'||!(d.kind==='notice'||d.status==='approved'))return {error:'결재가 완료된 공문이나 공람 안내를 선택해 주세요.'};if(!canWork(s,2))return {error:'수업·약속과 겹치지 않는 업무 시간 2분이 필요합니다.'};M.advance(s,2);d.status='completed';d.completed=M.stamp(s);d.history.push({date:d.completed,text:d.kind==='notice'?'안내 확인 · 공람 완료':'결재본 최종 제출 · 처리 완료'});M.log(s,d.title+' · 공문 처리 완료');sync(s);return {ok:true};}
export const statusLabel=d=>({received:'접수',draft:'기안 중',submitted:'결재 대기',revision:'보완 요청',approved:'결재 완료',completed:'처리 완료'})[d.status]||'접수';
export function valid(s){const pc=s.computer;if(pc===undefined)return true;const obj=x=>x&&typeof x==='object'&&!Array.isArray(x),str=(v,n)=>typeof v==='string'&&v.length<=n,unique=list=>new Set(list.map(x=>x.id)).size===list.length;
 if(!obj(pc)||pc.schema!==1||!Number.isInteger(pc.nextId)||pc.nextId<1||!obj(pc.weeks)||!Array.isArray(pc.notes)||pc.notes.length>100||!Array.isArray(pc.files)||pc.files.length>200||!Array.isArray(pc.official)||pc.official.length>50||![pc.notes,pc.files,pc.official].every(unique))return false;
 if(pc.notes.some(n=>!obj(n)||!/^sticky-[0-9]+$/.test(n.id)||!str(n.title,60)||!str(n.text,2000)||!NOTE_COLORS.includes(n.color)||typeof n.pinned!=='boolean'||typeof n.archived!=='boolean'||!str(n.created,100)||!str(n.updated,100)))return false;
 if(pc.files.some(f=>!obj(f)||!/^file-[0-9]+$/.test(f.id)||!Object.hasOwn(FILE_KINDS,f.kind)||!str(f.title,100)||!str(f.body,12000)||!str(f.created,100)||!str(f.updated,100)||typeof f.archived!=='boolean'))return false;
 return pc.official.every(d=>obj(d)&&/^official-[0-9]+-[01]$/.test(d.id)&&str(d.title,150)&&str(d.body,6000)&&str(d.number,150)&&str(d.from,100)&&str(d.received,100)&&['report','notice'].includes(d.kind)&&['received','draft','submitted','revision','approved','completed'].includes(d.status)&&Number.isInteger(d.due)&&d.due>=0&&d.due<M.demoDays(s)&&Number.isInteger(d.day)&&d.day>=0&&d.day<M.demoDays(s)&&str(d.reply,3000)&&Array.isArray(d.attachments)&&d.attachments.length<=5&&d.attachments.every(id=>pc.files.some(f=>f.id===id))&&Array.isArray(d.history)&&d.history.every(h=>str(h.date,100)&&str(h.text,600))&&(d.kind==='notice'?d.required===null:Object.hasOwn(FILE_KINDS,d.required))&&(!['submitted','revision','approved'].includes(d.status)||obj(d.submission)&&str(d.submission.text,3000)&&Array.isArray(d.submission.attachments)&&d.submission.attachments.length<=5&&d.submission.attachments.every(f=>obj(f)&&str(f.id,80)&&str(f.title,100)&&str(f.body,12000)&&Object.hasOwn(FILE_KINDS,f.kind)))&&(d.status!=='submitted'||Number.isInteger(d.reviewDay)&&d.reviewDay>=d.day&&d.reviewDay<M.demoDays(s)&&Number.isFinite(d.reviewMinute)&&d.reviewMinute>=520&&d.reviewMinute<=1000));
}
